<?php
namespace App\Http\Controllers\Admin;
use App\Enums\ReplacementStatus;use App\Http\Controllers\Controller;use App\Http\Requests\StoreAssignmentRequest;use App\Http\Requests\StoreReplacementRequest;use App\Http\Requests\UpdateReplacementStatusRequest;use App\Models\Assignment;use App\Models\ReplacementRequest;use App\Models\Service;use App\Models\Worker;use App\Services\ActivityLogger;use App\Services\ReplacementService;use App\Services\WorkerMatchingService;use Illuminate\Http\RedirectResponse;use Illuminate\Http\Request;use Illuminate\View\View;
class ReplacementController extends Controller { public function index(Request $request):View{$items=ReplacementRequest::with(['customer','oldWorker','newWorker','assignment.service'])->when($request->filled('status'),fn($q)=>$q->where('status',$request->input('status')))->when($request->filled('service'),fn($q)=>$q->whereHas('assignment',fn($a)=>$a->where('service_id',$request->integer('service'))))->when($request->filled('date'),fn($q)=>$q->whereDate('requested_date',$request->input('date')))->when($request->filled('search'),function($q)use($request){$t='%'.$request->string('search')->trim().'%';$q->where(fn($x)=>$x->where('replacement_code','like',$t)->orWhereHas('customer',fn($c)=>$c->where('name','like',$t))->orWhereHas('oldWorker',fn($w)=>$w->where('name','like',$t)));})->latest()->paginate(20)->withQueryString();return view('admin.replacements.index',['items'=>$items,'statuses'=>ReplacementStatus::cases(),'services'=>Service::where('is_active',true)->get()]);} public function store(StoreReplacementRequest $request,Assignment $assignment,ReplacementService $service,ActivityLogger $logger):RedirectResponse{$r=$service->create($assignment,$request->validated(),$request->user()->id);$logger->log('requested','replacements',$r,'Replacement requested.',['replacement_code'=>$r->replacement_code]);return redirect()->route('admin.replacements.show',$r)->with('success','Replacement request created.');} public function show(ReplacementRequest $replacement):View{$replacement->load(['assignment.service','customer','requirement','oldWorker','newWorker','replacementAssignment','statusHistory.changedBy']);return view('admin.replacements.show',compact('replacement'));} public function status(UpdateReplacementStatusRequest $request,ReplacementRequest $replacement,ReplacementService $service,ActivityLogger $logger):RedirectResponse{$old=$replacement->status->value;$service->updateStatus($replacement,ReplacementStatus::from($request->validated('status')),$request->validated('reason'),$request->user()->id);$logger->log($request->validated('status'),'replacements',$replacement,'Replacement status changed.',['from'=>$old,'to'=>$request->validated('status')]);return back()->with('success','Replacement status updated.');} public function matching(Request $request,ReplacementRequest $replacement,WorkerMatchingService $matching):View{$replacement->load(['requirement.customer','requirement.service','oldWorker']);$workers=$matching->candidates($replacement->requirement,$request->all(),$replacement->old_worker_id);return view('admin.replacements.matching',compact('replacement','workers'));} public function assign(StoreAssignmentRequest $request,ReplacementRequest $replacement,Worker $worker,ReplacementService $service,ActivityLogger $logger):RedirectResponse{$assignment=$service->assign($replacement,$worker,$request->validated(),$request->user()->id);$logger->log('worker_selected','replacements',$replacement,'Replacement worker selected.',['assignment_code'=>$assignment->assignment_code]);$logger->log('created','assignments',$assignment,'Replacement assignment created.',['replacement_code'=>$replacement->replacement_code]);return redirect()->route('admin.assignments.show',$assignment)->with('success','Replacement worker assigned in a new assignment.');} }
